import 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport 'dart:io';\nimport 'package:image_picker/image_picker.dart';\nimport 'package:flutter_image_compress/flutter_image_compress.dart';\nimport '../../../core/providers/core_providers.dart';\nimport '../../homework/models/homework.dart';\nimport '../../homework/providers/homework_providers.dart';\nimport 'package:uuid/uuid.dart';\nimport 'package:path_provider/path_provider.dart';\n\nclass AddHomeworkScreen extends ConsumerStatefulWidget {\n  const AddHomeworkScreen({Key? key}) : super(key: key);\n\n  @override\n  ConsumerState<AddHomeworkScreen> createState() => _AddHomeworkScreenState();\n}\n\nclass _AddHomeworkScreenState extends ConsumerState<AddHomeworkScreen> {\n  final _formKey = GlobalKey<FormState>();\n  final _titleController = TextEditingController();\n  final _descController = TextEditingController();\n  \n  String? _selectedClassId;\n  String? _selectedSubjectId;\n  File? _imageFile;\n  bool _isLoading = false;\n\n  @override\n  void dispose() {\n    _titleController.dispose();\n    _descController.dispose();\n    super.dispose();\n  }\n\n  Future<void> _pickImage(ImageSource source) async {\n    final picker = ImagePicker();\n    final pickedFile = await picker.pickImage(source: source);\n    \n    if (pickedFile != null) {\n      // Compress image\n      final dir = await getTemporaryDirectory();\n      final targetPath = '${dir.absolute.path}/temp_${const Uuid().v4()}.jpg';\n      \n      final compressedImage = await FlutterImageCompress.compressAndGetFile(\n        pickedFile.path,\n        targetPath,\n        quality: 70,\n      );\n      \n      if (compressedImage != null) {\n        setState(() => _imageFile = File(compressedImage.path));\n      }\n    }\n  }\n\n  Future<void> _submit() async {\n    if (!_formKey.currentState!.validate() || _selectedSubjectId == null) {\n      ScaffoldMessenger.of(context).showSnackBar(\n        const SnackBar(content: Text('الرجاء تعبئة جميع الحقول واختيار المادة')),\n      );\n      return;\n    }\n\n    setState(() => _isLoading = true);\n\n    try {\n      final supabase = ref.read(supabaseClientProvider);\n      String? imageUrl;\n\n      // Upload Image if exists\n      if (_imageFile != null) {\n        final fileExt = _imageFile!.path.split('.').last;\n        final fileName = '${const Uuid().v4()}.$fileExt';\n        final filePath = 'homework_images/$fileName';\n\n        await supabase.storage.from('school_storage').upload(filePath, _imageFile!);\n        imageUrl = supabase.storage.from('school_storage').getPublicUrl(filePath);\n      }\n\n      final newHomework = Homework(\n        id: const Uuid().v4(), // We can let Supabase generate it, but UUID package is handy here or let DB do it by omitting if model supports null ID\n        subjectId: _selectedSubjectId!,\n        title: _titleController.text.trim(),\n        description: _descController.text.trim(),\n        imageUrl: imageUrl,\n        createdAt: DateTime.now(),\n        isCurrent: true,\n        isDeleted: false,\n      );\n\n      await ref.read(homeworkServiceProvider).addHomework(newHomework);\n      \n      if (!mounted) return;\n      ScaffoldMessenger.of(context).showSnackBar(\n        const SnackBar(content: Text('تمت إضافة التحضير بنجاح')),\n      );\n      Navigator.pop(context);\n\n    } catch (e) {\n      if (!mounted) return;\n      ScaffoldMessenger.of(context).showSnackBar(\n        SnackBar(content: Text('خطأ: $e'), backgroundColor: Colors.red),\n      );\n    } finally {\n      if (mounted) setState(() => _isLoading = false);\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    // In a real app, teacher's school_id should be fetched from their profile.\n    // For this prototype, we assume the teacher knows their school or it's fetched from auth profile.\n    // Here we will use a dummy/hardcoded school ID or fetch from local if they somehow have it.\n    // Better: fetch teacher profile using auth.uid()\n    final user = ref.read(supabaseClientProvider).auth.currentUser;\n    // Note: You need a query to get teacher's schoolId. \n    // For now, let's assume we have it or we use a fallback to let them pick.\n    // This is a placeholder for `schoolId`.\n    final schoolId = 'dummy_school_id'; // Replace with real teacher's school_id query\n\n    final classesAsync = ref.watch(classesProvider(schoolId));\n\n    return Scaffold(\n      appBar: AppBar(title: const Text('إضافة تحضير جديد')),\n      body: _isLoading \n        ? const Center(child: CircularProgressIndicator()) \n        : SingleChildScrollView(\n            padding: const EdgeInsets.all(16.0),\n            child: Form(\n              key: _formKey,\n              child: Column(\n                crossAxisAlignment: CrossAxisAlignment.stretch,\n                children: [\n                  // Class Selection\n                  classesAsync.when(\n                    data: (classes) {\n                      return DropdownButtonFormField<String>(\n                        decoration: const InputDecoration(labelText: 'اختر الصف', border: OutlineInputBorder()),\n                        value: _selectedClassId,\n                        items: classes.map((c) => DropdownMenuItem(value: c.id, child: Text(c.name))).toList(),\n                        onChanged: (val) {\n                          setState(() {\n                            _selectedClassId = val;\n                            _selectedSubjectId = null; // Reset subject when class changes\n                          });\n                        },\n                      );\n                    },\n                    loading: () => const LinearProgressIndicator(),\n                    error: (e, _) => Text('خطأ في جلب الصفوف: $e'),\n                  ),\n                  const SizedBox(height: 16),\n\n                  // Subject Selection\n                  if (_selectedClassId != null)\n                    Consumer(\n                      builder: (context, ref, child) {\n                        final subjectsAsync = ref.watch(subjectsProvider(_selectedClassId!));\n                        return subjectsAsync.when(\n                          data: (subjects) {\n                            return DropdownButtonFormField<String>(\n                              decoration: const InputDecoration(labelText: 'اختر المادة', border: OutlineInputBorder()),\n                              value: _selectedSubjectId,\n                              items: subjects.map((s) => DropdownMenuItem(value: s.id, child: Text(s.name))).toList(),\n                              onChanged: (val) => setState(() => _selectedSubjectId = val),\n                            );\n                          },\n                          loading: () => const LinearProgressIndicator(),\n                          error: (e, _) => Text('خطأ في جلب المواد: $e'),\n                        );\n                      },\n                    ),\n                  const SizedBox(height: 16),\n\n                  TextFormField(\n                    controller: _titleController,\n                    decoration: const InputDecoration(labelText: 'عنوان التحضير (مثال: حل ص 24)', border: OutlineInputBorder()),\n                    validator: (val) => val == null || val.isEmpty ? 'مطلوب' : null,\n                  ),\n                  const SizedBox(height: 16),\n\n                  TextFormField(\n                    controller: _descController,\n                    maxLines: 5,\n                    decoration: const InputDecoration(labelText: 'نص التحضير والملاحظات', border: OutlineInputBorder()),\n                    validator: (val) => val == null || val.isEmpty ? 'مطلوب' : null,\n                  ),\n                  const SizedBox(height: 16),\n\n                  // Image Picker\n                  Row(\n                    children: [\n                      Expanded(\n                        child: ElevatedButton.icon(\n                          icon: const Icon(Icons.photo_library),\n                          label: const Text('المعرض'),\n                          onPressed: () => _pickImage(ImageSource.gallery),\n                        ),\n                      ),\n                      const SizedBox(width: 8),\n                      Expanded(\n                        child: ElevatedButton.icon(\n                          icon: const Icon(Icons.camera_alt),\n                          label: const Text('الكاميرا'),\n                          onPressed: () => _pickImage(ImageSource.camera),\n                        ),\n                      ),\n                    ],\n                  ),\n                  if (_imageFile != null) ...[\n                    const SizedBox(height: 16),\n                    Stack(\n                      alignment: Alignment.topRight,\n                      children: [\n                        Image.file(_imageFile!, height: 150, width: double.infinity, fit: BoxFit.cover),\n                        IconButton(\n                          icon: const Icon(Icons.cancel, color: Colors.red),\n                          onPressed: () => setState(() => _imageFile = null),\n                        )\n                      ],\n                    )\n                  ],\n                  const SizedBox(height: 32),\n\n                  ElevatedButton(\n                    onPressed: _submit,\n                    style: ElevatedButton.styleFrom(padding: const EdgeInsets.symmetric(vertical: 16)),\n                    child: const Text('نشر التحضير', style: TextStyle(fontSize: 18)),\n                  )\n                ],\n              ),\n            ),\n        ),\n    );\n  }\n}\n